-- Hand-written invariants (what the Prisma schema cannot express)
-- Each status carries exactly its own payload: no failure reason outside FAILED; the extraction exists
-- from ANALYZING on, and ANALYZING has the posting text `cv.tailor` reads. A pasted posting always has
-- its text while it waits for `job.fetch`.
ALTER TABLE "job_postings" ADD CONSTRAINT "job_postings_status_payload_check" CHECK (
  CASE "status"
    WHEN 'FETCHING' THEN "failure_reason" IS NULL AND "extracted" IS NULL
      AND ("source" <> 'PASTED' OR "page_text" IS NOT NULL)
    WHEN 'ANALYZING' THEN "failure_reason" IS NULL AND "extracted" IS NOT NULL AND "page_text" IS NOT NULL
    WHEN 'READY' THEN "failure_reason" IS NULL AND "extracted" IS NOT NULL
    WHEN 'FAILED' THEN "failure_reason" IS NOT NULL
  END
);
-- Bounds mirror the contract (`JOB_POSTING_LIMITS`): the URL is http(s), the hash is sha256 hex, the text
-- is the sanitized, truncated page text.
ALTER TABLE "job_postings" ADD CONSTRAINT "job_postings_url_check"
  CHECK ("url" ~ '^https?://' AND char_length("url") <= 2048);
ALTER TABLE "job_postings" ADD CONSTRAINT "job_postings_url_hash_check" CHECK ("url_hash" ~ '^[0-9a-f]{64}$');
ALTER TABLE "job_postings" ADD CONSTRAINT "job_postings_page_text_check"
  CHECK ("page_text" IS NULL OR char_length("page_text") BETWEEN 1 AND 20000);
ALTER TABLE "job_postings" ADD CONSTRAINT "job_postings_extracted_check"
  CHECK ("extracted" IS NULL OR (jsonb_typeof("extracted") = 'object' AND octet_length("extracted"::text) <= 262144));
ALTER TABLE "job_postings" ADD CONSTRAINT "job_postings_dropped_requirement_count_check"
  CHECK ("dropped_requirement_count" IS NULL OR "dropped_requirement_count" >= 0);
ALTER TABLE "job_postings" ADD CONSTRAINT "job_postings_injection_evidence_check"
  CHECK ("injection_evidence" IS NULL OR ("injection_suspected" AND char_length("injection_evidence") BETWEEN 1 AND 500));
ALTER TABLE "job_postings" ADD CONSTRAINT "job_postings_generation_check"
  CHECK ("generation" IS NULL OR jsonb_typeof("generation") = 'object');
ALTER TABLE "tailored_cvs" ADD CONSTRAINT "tailored_cvs_json_check" CHECK (
  jsonb_typeof("content") = 'object' AND octet_length("content"::text) <= 262144
  AND jsonb_typeof("match_report") = 'object' AND octet_length("match_report"::text) <= 262144
  AND jsonb_typeof("generation") = 'object'
);
